from pathlib import Path; import json,math,numpy as np
out=Path(__file__).parent; rows=json.loads((out/'e2-decoded-predictions.json').read_text())['rows']; rules=[('full',lambda f:f)]+[(str(bits)+mode,(lambda f,bits=bits,mode=mode:(math.floor(f*2**bits+.5) if mode=='nearest' else math.floor(f*2**bits))/2**bits)) for bits in [8,9,10,16] for mode in ['floor','nearest']]
weights=lambda r,q:(lambda a,b:[(1-a)*(1-b),a*(1-b),(1-a)*b,a*b])(q(r['sample_xy'][0]%1),q(r['sample_xy'][1]%1)); trials=[{'texture':tex,'rule':name,'convert':conv,'predictions':[int((math.floor if conv=='floor' else lambda a:math.floor(a+.5))(r['B']+(255-r['B'])*float(np.dot(weights(r,q),r[tex]))/255)) for r in rows]} for tex in ['gpu_alpha_bytes','exact_alpha_bytes'] for name,q in rules for conv in ['floor','nearest']]
[t.update({'native_mismatches':sum(a!=r['native'] for a,r in zip(t['predictions'],rows)),'web_mismatches':sum(a!=r['web'] for a,r in zip(t['predictions'],rows))}) for t in trials]
(out/'e3-subtexel-rules.json').write_text(json.dumps({'rows_order':[r['pixel'] for r in rows],'trials':trials},indent=2),encoding='utf8'); print(sorted([{k:v for k,v in t.items() if k!='predictions'} for t in trials],key=lambda t:t['native_mismatches'])[:8])
